import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const publicModules = [
  "ji-java/core/ji-ai-api/src/main/java",
  "ji-java/core/ji-agent-api/src/main/java",
  "ji-java/core/ji-session-api/src/main/java",
  "ji-java/core/ji-security-api/src/main/java",
  "ji-java/core/ji-extension-api/src/main/java",
  "ji-java/core/ji-artifact-api/src/main/java",
  "ji-java/core/ji-telemetry-api/src/main/java",
];
const forbiddenImports = [
  "org.springframework.",
  "reactor.",
  "java.sql.",
  "com.fasterxml.jackson.",
  "com.agentclientprotocol.",
  "io.github.diodeme.ji.hcp.",
];
const failures = [];
for (const modulePath of publicModules) {
  for (const file of await javaFiles(path.join(root, modulePath))) {
    const text = await readFile(file, "utf8");
    for (const forbidden of forbiddenImports) {
      if (text.includes(`import ${forbidden}`)) failures.push(`${path.relative(root, file)} imports ${forbidden}`);
    }
  }
}
if (failures.length > 0) throw new Error(`public module boundary violations:\n${failures.join("\n")}`);
process.stdout.write("public Java module boundaries verified\n");

async function javaFiles(directory) {
  const files = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const child = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...await javaFiles(child));
    else if (entry.name.endsWith(".java")) files.push(child);
  }
  return files;
}
